class apb_main_seq extends apb_base_seq;
  `uvm_object_utils(apb_main_seq)

  rand int num_trans;
  constraint c_trans { num_trans inside {[30:60]}; }

  function new(string name="apb_main_seq"); super.new(name); endfunction

  virtual task body();
    apb_seq_item req;

    // Randomize num_trans if not already set
    if (num_trans == 0) begin
      if (!this.randomize())
        `uvm_fatal("SEQ", "Failed to randomize num_trans")
    end

    `uvm_info("SEQ", $sformatf("Generating %0d random transactions", num_trans), UVM_LOW)

    // 1. Constrained Random with occasional idle gaps to exercise
    //    ACCESS->IDLE (CA-5a) and IDLE->SETUP (CA-2) transitions.
    for (int i = 0; i < num_trans; i++) begin
      req = apb_seq_item::type_id::create("req");
      start_item(req);
      if (!req.randomize()) `uvm_error("SEQ", "Randomization failed")
      finish_item(req);

      // Insert a gap roughly every 4-5 transactions so the driver's
      // try_next_item() returns null and PSEL drops to IDLE.
      // 30% chance of gap → ~17 ACCESS->IDLE events over 55 transactions.
      if (($urandom_range(0, 9) < 3) && (i < num_trans - 1)) begin
        // Wait long enough for the driver to complete the current
        // transaction and find an empty queue. 3 cycles = 30ns is
        // plenty given a 10ns clock period.
