    end

    // 2. Back-to-back burst (no gaps) to keep stressing CA-5b.
    for (int i = 0; i < 5; i++) begin
      req = apb_seq_item::type_id::create("req");
      start_item(req);
      if (!req.randomize() with { paddr[5] == 1'b0; })
        `uvm_error("SEQ", "B2B Randomization failed")
