class apb_driver extends uvm_driver #(apb_seq_item);
  `uvm_component_utils(apb_driver)

  virtual apb_if vif;

  function new(string name, uvm_component parent);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db#(virtual apb_if)::get(this, "", "vif", vif))
      `uvm_fatal("DRV", "Failed to get virtual interface")
  endfunction

  virtual task run_phase(uvm_phase phase);
    apb_seq_item req;

    // Initialize signals (these NBAs take effect at the next posedge PCLK)
    vif.drv_cb.PSEL    <= 1'b0;
    vif.drv_cb.PENABLE <= 1'b0;
    vif.drv_cb.PADDR   <= 32'h0;
    vif.drv_cb.PWDATA  <= 32'h0;
    vif.drv_cb.PWRITE  <= 1'b0;

    // Wait for reset deassertion AND give one clock for NBAs to propagate
    wait(vif.PRESETn === 1'b1);
    @(vif.drv_cb);

    // Initial item get
    seq_item_port.get_next_item(req);

    forever begin
      // --- SETUP Phase ---
      vif.drv_cb.PSEL    <= 1'b1;
      vif.drv_cb.PENABLE <= 1'b0;
      vif.drv_cb.PADDR   <= req.paddr;
      vif.drv_cb.PWRITE  <= req.pwrite;
      vif.drv_cb.PWDATA  <= req.pwdata;

      @(vif.drv_cb);

      // --- ACCESS Phase ---
      // Assert PENABLE, then sample PREADY at each subsequent posedge.
      // do/while ensures we don't sample PREADY in the SETUP cycle.
      vif.drv_cb.PENABLE <= 1'b1;
      do begin
        @(vif.drv_cb);
      end while (vif.drv_cb.PREADY !== 1'b1);

      // Sample APB completer outputs
      req.prdata  = vif.drv_cb.PRDATA;
      req.pslverr = vif.drv_cb.PSLVERR;
      req.pready  = vif.drv_cb.PREADY;

      seq_item_port.item_done();

      // Check for back-to-back transfer (CA-5b)
      req = null;
      seq_item_port.try_next_item(req);

      if (req == null) begin
        // No immediate item: drop to IDLE phase (CA-5a)
        vif.drv_cb.PSEL    <= 1'b0;
        vif.drv_cb.PENABLE <= 1'b0;

        // Wait for next item
        seq_item_port.get_next_item(req);
      end
      // If req is not null, loop back to SETUP without dropping PSEL
    end
  endtask
endclass
