  endfunction

  virtual function void write(apb_seq_item item);
    bit [4:0] idx = item.paddr[4:0];
    bit       is_oob = item.paddr[5];

    // Check Out-of-Bounds behavior
    if (is_oob) begin
      if (item.pslverr !== 1'b1) begin
        `uvm_error("SCB_FAIL", $sformatf("Missing PSLVERR for OOB address: %0h", item.paddr))
      end else begin
        `uvm_info("SCB_PASS", $sformatf("OOB Access trapped correctly at addr: %0h", item.paddr), UVM_HIGH)
      end
    end 
    // Check In-Bounds behavior
    else begin
      if (item.pslverr === 1'b1) begin
        `uvm_error("SCB_FAIL", $sformatf("Spurious PSLVERR for valid address: %0h", item.paddr))
      end else begin
        if (item.pwrite) begin
          ref_mem[idx] = item.pwdata;
          `uvm_info("SCB_WRITE", $sformatf("Written mem[%0d] = %0h", idx, item.pwdata), UVM_HIGH)
        end else begin
          if (item.prdata !== ref_mem[idx]) begin
            `uvm_error("SCB_FAIL", $sformatf("Read mismatch at mem[%0d]. Exp: %0h, Act: %0h", 
                                             idx, ref_mem[idx], item.prdata))
          end else begin
            `uvm_info("SCB_PASS", $sformatf("Read match at mem[%0d] = %0h", idx, item.prdata), UVM_HIGH)
          end
        end
      end
    end
  endfunction
