class apb_coverage extends uvm_subscriber #(apb_seq_item);
  `uvm_component_utils(apb_coverage)

  apb_seq_item item;

  covergroup apb_cg;
    option.per_instance = 1;

    cp_pwrite: coverpoint item.pwrite {
      bins read  = {0};
      bins write = {1};
    }

    cp_pslverr: coverpoint item.pslverr {
      bins no_error = {0};
      bins error    = {1};
    }

    cp_addr_validity: coverpoint item.paddr[5] {
      bins valid         = {0};
      bins out_of_bounds = {1};
    }
    
    cp_addr_corners: coverpoint item.paddr[4:0] {
      bins min_addr = {5'd0};
      bins max_addr = {5'd31};
      bins others   = {[1:30]};
    }

    // Cross combinations to ensure read/write occur in both valid and error modes
    cr_write_validity: cross cp_pwrite, cp_addr_validity;
    cr_write_corners:  cross cp_pwrite, cp_addr_corners;
  endgroup

  function new(string name, uvm_component parent);
    super.new(name, parent);
    apb_cg = new();
  endfunction

  virtual function void write(apb_seq_item t);
    item = t;
    apb_cg.sample();
  endfunction
