module tb_top;
  logic PCLK;
  logic PRESETn;

  apb_if vif(.PCLK(PCLK));

  apb_memory dut (
    .PCLK    (PCLK),
    .PRESETn (PRESETn),
    .PADDR   (vif.PADDR),
    .PWDATA  (vif.PWDATA),
    .PSEL    (vif.PSEL),
    .PENABLE (vif.PENABLE),
    .PWRITE  (vif.PWRITE),
    .PRDATA  (vif.PRDATA),
    .PREADY  (vif.PREADY),
    .PSLVERR (vif.PSLVERR)
  );

  // Tie interface reset to TB reset
  assign vif.PRESETn = PRESETn;

  // Clock Generation — 100 MHz
  initial begin
    PCLK = 1'b0;
    forever #5 PCLK = ~PCLK;
  end

  // Reset Generation (active low). Hold reset for several clocks
  // so the interface initial block and driver NBAs are settled.
  initial begin
    PRESETn = 1'b0;
    #45;             // 4+ clock cycles of reset
    PRESETn = 1'b1;
  end

  initial begin
    uvm_config_db#(virtual apb_if)::set(null, "*", "vif", vif);
    run_test("apb_test");
  end
endmodule
